mapper.select:
select t.task_id as taskId, t.task_code as taskCode, t.workorder_code as workorderCode, t.process_name as processName, t.workstation_name as workstationName, t.plan_quantity as planQuantity, t.completed_quantity as completedQuantity, t.status, w.item_name as itemName, round(ifnull(t.completed_quantity / t.plan_quantity * 100, 0), 1) as progress, timestampdiff(hour, t.plan_start_time, now()) as waitHours from pro_task t left join pro_workorder w on t.workorder_id = w.workorder_id where t.status in ('PENDING', 'PROCESSING')
and t.workstation_id = #{workstationId}
order by t.status = 'PROCESSING' desc, t.plan_start_time asc
